import heapq
grid = ['..#.', '..#.', '....']
def h(p, g): return abs(p[0]-g[0]) + abs(p[1]-g[1])
def astar(s, g):
    pq = [(h(s,g), 0, s)]; best = {s: 0}
    while pq:
        f, c, p = heapq.heappop(pq)
        if p == g: return c
        for d in [(0,1),(1,0),(0,-1),(-1,0)]:
            q = (p[0]+d[0], p[1]+d[1])
            if 0<=q[0]<3 and 0<=q[1]<4 and grid[q[0]][q[1]]=='.' and c+1 < best.get(q, 99):
                best[q] = c+1; heapq.heappush(pq, (c+1+h(q,g), c+1, q))
print('shortest path cost:', astar((0,0),(0,3)))
